import { inject } from '@angular/core';
import { Router } from '@angular/router';
import { map } from 'rxjs/operators';
import { getRoutePath, searchRoutePath } from '../app.routes';
import { ProfileService } from '../profile/profile.service';

export const canActivateAdmin = () => {
  const profileService = inject(ProfileService);
  const router = inject(Router);

  return profileService.isAdmin$.pipe(
    map((isAdmin) => {
      if (isAdmin) {
        return true;
      }

      // Redirect to search page if user is not admin
      return router.createUrlTree([getRoutePath(searchRoutePath)]);
    })
  );
};
